def parse_date(text: str) -> Optional[_date]:
    """A real YYYY-MM-DD date, or None."""
    if not _DATE_RE.fullmatch(text):
        return None
    try:
        return _date(int(text[0:4]), int(text[5:7]), int(text[8:10]))
    except ValueError:
        return None


def _records(text: str) -> Iterator[Tuple[int, str]]:
    """(line number, trimmed line) for every line that is not blank or a comment."""
    if text.startswith("﻿"):
        text = text[1:]
    for number, raw in enumerate(text.split("\n"), 1):
        if raw.endswith("\r"):
            raw = raw[:-1]
        line = raw.strip(" \t")
        if not line or line.startswith("#"):
            continue
        yield number, line


def bounded_int(text: str) -> Optional[int]:
    """int(text) for an optionally signed run of digits, or None if it is too large."""
    sign = "-" if text.startswith("-") else ""
    digits = text.lstrip("+-").lstrip("0") or "0"
    if len(digits) > len(str(MAX_QUANTITY)):
        return None
    value = int(sign + digits)
    return value if abs(value) <= MAX_QUANTITY else None


def _int(text: str, lineno: int, what: str) -> int:
    value = bounded_int(text)
    if value is None:
        raise ParseError(lineno, "%s %r is too large" % (what, _short(text)))
    return value


def _short(text: str) -> str:
    return text if len(text) <= 30 else text[:27] + "..."


def _date_field(text: str, lineno: int) -> _date:
    parsed = parse_date(text)
    if parsed is None:
        raise ParseError(lineno, "bad date %r (want a real YYYY-MM-DD date)" % text)
    return parsed


